class Solution {
public:
    int smallestDivisor(std::vector<int>& nums, int threshold) {
        auto computeSum = [&](int d) -> long long {
            long long s = 0;
            for (int x : nums) s += (x + d - 1) / d;
            return s;
        };

        int low = 1, high = *std::max_element(nums.begin(), nums.end()), ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (computeSum(mid) <= threshold) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int smallestDivisor(int[] nums, int threshold) {
        int maxVal = 0;
        for (int x : nums) if (x > maxVal) maxVal = x;

        int low = 1, high = maxVal, ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            long s = 0;
            for (int x : nums) s += (x + mid - 1) / mid;
            if (s <= threshold) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
}

var smallestDivisor = function(nums, threshold) {
    let maxVal = 0;
    for (const x of nums) if (x > maxVal) maxVal = x;

    let low = 1, high = maxVal, ans = high;
    while (low <= high) {
        const mid = (low + high) >> 1;
        let s = 0;
        for (const x of nums) s += Math.floor((x + mid - 1) / mid);
        if (s <= threshold) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
};
